   138→public(package) fun cancel_pool_reward<CoinType>(
   139→    pool_reward_manager: &mut PoolRewardManager,
   140→    index: u64,
   141→    clock: &Clock,
   142→): Balance<CoinType>{
   143→    update_pool_reward_manager(pool_reward_manager, clock);
   144→    
   145→    let pool_reward = pool_reward_manager.pool_rewards.borrow_mut(index).borrow_mut();
   146→    let cur_time_ms = clock.timestamp_ms();
   147→    
   148→    let unallocated_rewards = 
   149→        float::from(pool_reward.total_rewards).sub(
   150→        pool_reward.allocated_rewards
   151→        ).floor();
   152→    
   153→    pool_reward.end_time_ms = cur_time_ms;
   154→    pool_reward.total_rewards = 0;
   155→
   156→    let reward_balance = pool_reward.additional_fields.borrow_mut<RewardBalance<CoinType>, Balance<CoinType>>(RewardBalance<CoinType>{});
   157→
   158→    reward_balance.split(unallocated_rewards)
   159→}
